#include "test_assert.hpp"
#include "model_loader.hpp"
#include "backend.hpp"
#include "rfdetr.h"
#include <algorithm>
#include <string>
#include <vector>

/* Collects RFDETR_LOG_ERROR messages into the vector passed as user_data, so a
 * test can assert on what an error path actually told the user. */
static void capture_errors_cb(rfdetr_log_level lvl, const char* msg, void* ud) {
    if (lvl == RFDETR_LOG_ERROR) {
        static_cast<std::vector<std::string>*>(ud)->emplace_back(msg);
    }
}

int main() {
    const std::string fixtures = RFDETR_TEST_FIXTURES;
    const std::string path = fixtures + "/model_base.gguf";

    rfdetr_status st;
    rfdetr::Model* m = rfdetr::model_load(path, &st);
    RFDETR_ASSERT(m != nullptr);
    RFDETR_ASSERT_EQ_INT(st, RFDETR_OK);

    // Config
    RFDETR_ASSERT_STR_EQ(m->config.variant.c_str(), "base");
    RFDETR_ASSERT_EQ_INT(m->config.image_size,  56);
    RFDETR_ASSERT_EQ_INT(m->config.patch_size,  14);
    RFDETR_ASSERT_EQ_INT(m->config.num_queries, 300);
    RFDETR_ASSERT_EQ_INT(m->config.group_detr,  13);
    RFDETR_ASSERT_EQ_INT(m->config.num_classes, 91);
    RFDETR_ASSERT_EQ_INT(m->config.class_names.size(), 91);
    // Position 0 is COCO id 0 ("person"); position 90 is "toothbrush" (id 90).
    RFDETR_ASSERT_STR_EQ(m->config.class_names[0].c_str(),  "person");
    RFDETR_ASSERT_STR_EQ(m->config.class_names[90].c_str(), "toothbrush");

    // Preprocess
    RFDETR_ASSERT_NEAR(m->config.preprocess_mean[0], 0.485f, 1e-4);
    RFDETR_ASSERT_NEAR(m->config.preprocess_std[2],  0.225f, 1e-4);
    // This fixture carries no rfdetr.preprocess.resize_mode key, exactly like
    // every GGUF converted before that key existed. Absent must mean the
    // legacy stb resize, or those files silently change their output. Do not
    // "fix" a failure here by stamping the key into the fixture; the absence
    // is the thing under test.
    RFDETR_ASSERT(m->config.preprocess_bilinear_no_antialias == false);

    // Backbone (shrunk fixture: dim=64, depth=12, heads=8, ffn=128, 4 windows)
    RFDETR_ASSERT_EQ_INT(m->config.backbone.dim,          64);
    RFDETR_ASSERT_EQ_INT(m->config.backbone.depth,        12);
    RFDETR_ASSERT_EQ_INT(m->config.backbone.heads,        8);
    RFDETR_ASSERT_EQ_INT(m->config.backbone.ffn_dim,      128);
    RFDETR_ASSERT_EQ_INT(m->config.backbone.num_windows,  4);
    RFDETR_ASSERT_EQ_INT(m->config.backbone.global_attn_indices.size(), 4);
    RFDETR_ASSERT_EQ_INT(m->config.backbone.global_attn_indices[0], 2);
    RFDETR_ASSERT_EQ_INT(m->config.backbone.global_attn_indices[3], 11);
    RFDETR_ASSERT_EQ_INT(m->config.backbone.out_feature_indices.size(), 4);
    RFDETR_ASSERT_EQ_INT(m->config.backbone.out_feature_indices[0], 2);
    RFDETR_ASSERT_EQ_INT(m->config.backbone.out_feature_indices[3], 11);
    RFDETR_ASSERT_EQ_INT(m->config.backbone.pos_embed_train_size, 4);

    // Projector
    RFDETR_ASSERT_EQ_INT(m->config.projector.in_dim,         256); // 4 * 64
    RFDETR_ASSERT_EQ_INT(m->config.projector.out_dim,        64);
    RFDETR_ASSERT_EQ_INT(m->config.projector.bottleneck_dim, 32);
    RFDETR_ASSERT_EQ_INT(m->config.projector.n_bottlenecks,  3);

    // Decoder
    RFDETR_ASSERT_EQ_INT(m->config.decoder.layers,              3);
    RFDETR_ASSERT_EQ_INT(m->config.decoder.model_dim,           64);
    RFDETR_ASSERT_EQ_INT(m->config.decoder.ffn_dim,             128);
    RFDETR_ASSERT_EQ_INT(m->config.decoder.self_attn_heads,     8);
    RFDETR_ASSERT_EQ_INT(m->config.decoder.cross_attn_heads,    8);
    RFDETR_ASSERT_EQ_INT(m->config.decoder.cross_attn_n_levels, 1);
    RFDETR_ASSERT_EQ_INT(m->config.decoder.cross_attn_n_points, 2);

    // Two-stage
    RFDETR_ASSERT_EQ_INT(m->config.two_stage.n_groups, 13);

    // Tensors present (sample a few from each section)
    RFDETR_ASSERT(m->tensors.count("backbone.patch_embed.weight") == 1);
    RFDETR_ASSERT(m->tensors.count("backbone.cls_token") == 1);
    RFDETR_ASSERT(m->tensors.count("backbone.pos_embed") == 1);
    RFDETR_ASSERT(m->tensors.count("backbone.blocks.0.attn.q.weight") == 1);
    RFDETR_ASSERT(m->tensors.count("backbone.blocks.0.attn.k.weight") == 1);
    RFDETR_ASSERT(m->tensors.count("backbone.blocks.0.attn.v.weight") == 1);
    RFDETR_ASSERT(m->tensors.count("backbone.blocks.0.layer_scale1") == 1);
    RFDETR_ASSERT(m->tensors.count("backbone.blocks.11.layer_scale2") == 1);
    RFDETR_ASSERT(m->tensors.count("backbone.blocks.11.mlp.fc2.bias") == 1);
    RFDETR_ASSERT(m->tensors.count("projector.cv1.conv.weight") == 1);
    RFDETR_ASSERT(m->tensors.count("projector.bottleneck.0.cv1.conv.weight") == 1);
    RFDETR_ASSERT(m->tensors.count("projector.bottleneck.2.cv2.norm.bias") == 1);
    RFDETR_ASSERT(m->tensors.count("projector.final_norm.weight") == 1);
    RFDETR_ASSERT(m->tensors.count("two_stage.enc_output.0.weight") == 1);
    RFDETR_ASSERT(m->tensors.count("two_stage.enc_output.12.bias") == 1);
    RFDETR_ASSERT(m->tensors.count("two_stage.enc_out_bbox_embed.0.layers.2.bias") == 1);
    RFDETR_ASSERT(m->tensors.count("decoder.queries.feat") == 1);
    RFDETR_ASSERT(m->tensors.count("decoder.queries.refpoints") == 1);
    RFDETR_ASSERT(m->tensors.count("decoder.ref_point_head.layers.0.weight") == 1);
    RFDETR_ASSERT(m->tensors.count("decoder.layers.0.self_attn.in_proj.weight") == 1);
    RFDETR_ASSERT(m->tensors.count("decoder.layers.2.cross_attn.sampling_offsets.weight") == 1);
    RFDETR_ASSERT(m->tensors.count("decoder.layers.2.cross_attn.value_proj.weight") == 1);
    RFDETR_ASSERT(m->tensors.count("decoder.norm.weight") == 1);
    RFDETR_ASSERT(m->tensors.count("heads.class_embed.weight") == 1);
    RFDETR_ASSERT(m->tensors.count("heads.bbox_embed.layers.2.weight") == 1);

    // Validation passes
    rfdetr_status v = rfdetr::model_validate_tensors(*m);
    RFDETR_ASSERT_EQ_INT(v, RFDETR_OK);

    // Bad path -> error
    rfdetr_status st2;
    rfdetr::Model* bad = rfdetr::model_load("/no/such/path.gguf", &st2);
    RFDETR_ASSERT(bad == nullptr);
    RFDETR_ASSERT(st2 == RFDETR_ERR_FILE_NOT_FOUND || st2 == RFDETR_ERR_MODEL_FORMAT);

    rfdetr::model_free(m);

    // ---- Missing tensor -> validation fails ----
    {
        std::string bad_path = fixtures + "/model_base_missing.gguf";
        rfdetr_status st_;
        rfdetr::Model* bm = rfdetr::model_load(bad_path, &st_);
        RFDETR_ASSERT(bm != nullptr);
        RFDETR_ASSERT_EQ_INT(st_, RFDETR_OK);

        rfdetr_status v = rfdetr::model_validate_tensors(*bm);
        RFDETR_ASSERT_EQ_INT(v, RFDETR_ERR_MODEL_LOAD);

        rfdetr::model_free(bm);
    }

    // ---- rfdetr.preprocess.resize_mode: explicit values ----
    // The absent-key case is asserted above on model_base.gguf. These two cover
    // the values a converter can actually write.
    {
        rfdetr_status st_;
        rfdetr::Model* bl = rfdetr::model_load(
            fixtures + "/model_base_resize_bilinear.gguf", &st_);
        RFDETR_ASSERT(bl != nullptr);
        RFDETR_ASSERT_EQ_INT(st_, RFDETR_OK);
        RFDETR_ASSERT(bl->config.preprocess_bilinear_no_antialias == true);
        rfdetr::model_free(bl);

        // An unrecognized mode is a hard error, not a silent fall back to
        // legacy: quietly ignoring it would hide a converter/runtime skew and
        // produce wrong preprocessing with no signal.
        std::vector<std::string> errors;
        rfdetr_set_log_callback(capture_errors_cb, &errors);
        rfdetr_status st_bogus = RFDETR_OK;
        rfdetr::Model* bogus = rfdetr::model_load(
            fixtures + "/model_base_resize_bogus.gguf", &st_bogus);
        rfdetr_set_log_callback(nullptr, nullptr);

        RFDETR_ASSERT(bogus == nullptr);
        RFDETR_ASSERT_EQ_INT(st_bogus, RFDETR_ERR_MODEL_FORMAT);
        // The message must name the key so the user knows what to look at.
        RFDETR_ASSERT(!errors.empty());
        bool named_key = false;
        for (const auto& e : errors) {
            if (e.find("resize_mode") != std::string::npos) named_key = true;
        }
        RFDETR_ASSERT(named_key);
    }

    // ---- expected_tensor_names produces the right count for base ----
    {
        rfdetr_status st_;
        rfdetr::Model* good = rfdetr::model_load(path, &st_);
        std::vector<std::string> expected = rfdetr::expected_tensor_names(good->config);
        // Loader counted all tensor names; expected list should match.
        RFDETR_ASSERT_EQ_INT(expected.size(), good->tensors.size());
        for (const auto& n : expected) {
            RFDETR_ASSERT(good->tensors.count(n) == 1);
        }
        // Sanity: 486 tensors for the v2 base schema.
        RFDETR_ASSERT_EQ_INT(expected.size(), 486);
        rfdetr::model_free(good);
    }

    // ---- Realize weights into a backend buffer ----
    {
        rfdetr_status st_;
        rfdetr::Model* mm = rfdetr::model_load(path, &st_);
        RFDETR_ASSERT(mm != nullptr);

        ggml_backend_t backend = rfdetr::init_backend(1, &st_);
        RFDETR_ASSERT(backend != nullptr);
        RFDETR_ASSERT_EQ_INT(st_, RFDETR_OK);

        rfdetr_status rs = rfdetr::model_realize_weights(*mm, backend);
        RFDETR_ASSERT_EQ_INT(rs, RFDETR_OK);
        RFDETR_ASSERT(mm->weights != nullptr);

        /* Idempotent: a second call is OK */
        rfdetr_status rs2 = rfdetr::model_realize_weights(*mm, backend);
        RFDETR_ASSERT_EQ_INT(rs2, RFDETR_OK);

        rfdetr::model_free(mm);
        rfdetr::free_backend(backend);
    }

    // ---- realize_weights error paths ----
    {
        rfdetr_status st_;
        rfdetr::Model* mm = rfdetr::model_load(path, &st_);
        RFDETR_ASSERT(mm != nullptr);

        // Null backend → INVALID_ARG
        RFDETR_ASSERT_EQ_INT(rfdetr::model_realize_weights(*mm, nullptr),
                             RFDETR_ERR_INVALID_ARG);

        rfdetr::model_free(mm);
    }

    // ---- Seg head has one block per decoder layer, not a hardcoded 4 ----
    {
        // A 5-decoder-layer seg variant (seg-medium) must expect blocks 0..4.
        rfdetr::Config cfg;
        cfg.has_segmentation_head = true;
        cfg.decoder.layers = 5;
        std::vector<std::string> names = rfdetr::expected_tensor_names(cfg);

        auto has = [&names](const std::string& n) {
            return std::find(names.begin(), names.end(), n) != names.end();
        };
        RFDETR_ASSERT(has("segmentation_head.blocks.0.dwconv.weight"));
        RFDETR_ASSERT(has("segmentation_head.blocks.4.dwconv.weight"));
        RFDETR_ASSERT(has("segmentation_head.blocks.4.pwconv1.bias"));
        RFDETR_ASSERT(!has("segmentation_head.blocks.5.dwconv.weight"));

        // A 6-layer variant (seg-xlarge) expects blocks 0..5.
        rfdetr::Config cfg6;
        cfg6.has_segmentation_head = true;
        cfg6.decoder.layers = 6;
        std::vector<std::string> names6 = rfdetr::expected_tensor_names(cfg6);
        auto has6 = [&names6](const std::string& n) {
            return std::find(names6.begin(), names6.end(), n) != names6.end();
        };
        RFDETR_ASSERT(has6("segmentation_head.blocks.5.dwconv.weight"));

        // A 4-layer variant (seg-nano) is unchanged: blocks 0..3 only.
        rfdetr::Config cfg4;
        cfg4.has_segmentation_head = true;
        cfg4.decoder.layers = 4;
        std::vector<std::string> names4 = rfdetr::expected_tensor_names(cfg4);
        auto has4 = [&names4](const std::string& n) {
            return std::find(names4.begin(), names4.end(), n) != names4.end();
        };
        RFDETR_ASSERT(has4("segmentation_head.blocks.3.dwconv.weight"));
        RFDETR_ASSERT(!has4("segmentation_head.blocks.4.dwconv.weight"));
    }

    // ---- Pre-fix seg GGUFs are rejected with a specific error ----
    {
        // A Model is default-constructible; count_segmentation_blocks only
        // checks key presence, so nullptr tensor values are fine here.
        rfdetr::Model fake;
        fake.config.has_segmentation_head = true;
        fake.config.decoder.layers = 5;

        // Simulate a GGUF converted before the fix: only 4 blocks present.
        for (int b = 0; b < 4; ++b) {
            const std::string p =
                "segmentation_head.blocks." + std::to_string(b) + ".";
            fake.tensors[p + "dwconv.weight"] = nullptr;
        }
        RFDETR_ASSERT_EQ_INT((int)rfdetr::count_segmentation_blocks(fake), 4);

        /* The status alone cannot distinguish the guard from the generic
         * missing-tensor path: a short block count always implies missing
         * expected names, so both return RFDETR_ERR_MODEL_LOAD. The message is
         * the deliverable, so assert on the message. */
        std::vector<std::string> errors;
        rfdetr_set_log_callback(capture_errors_cb, &errors);

        rfdetr_status v = rfdetr::model_validate_tensors(fake);
        RFDETR_ASSERT_EQ_INT(v, RFDETR_ERR_MODEL_LOAD);

        RFDETR_ASSERT_EQ_INT(errors.size(), 1);
        const std::string& stale = errors[0];
        // Names both counts: what the file has, and what the model needs.
        RFDETR_ASSERT(stale.find("4 head block") != std::string::npos);
        RFDETR_ASSERT(stale.find("5 decoder layers") != std::string::npos);
        // Names the cause and the remedy.
        RFDETR_ASSERT(stale.find("converted before") != std::string::npos);
        RFDETR_ASSERT(stale.find("convert_rfdetr_to_gguf.py") != std::string::npos);
        // And is not the generic missing-tensor message the guard replaces.
        RFDETR_ASSERT(stale.find("missing tensor") == std::string::npos);

        // Seg metadata but no seg tensors at all is a different fault, and the
        // stale-file cause must not be asserted for it.
        errors.clear();
        rfdetr::Model empty_seg;
        empty_seg.config.has_segmentation_head = true;
        empty_seg.config.decoder.layers = 5;
        RFDETR_ASSERT_EQ_INT((int)rfdetr::count_segmentation_blocks(empty_seg), 0);
        RFDETR_ASSERT_EQ_INT(rfdetr::model_validate_tensors(empty_seg),
                             RFDETR_ERR_MODEL_LOAD);
        RFDETR_ASSERT_EQ_INT(errors.size(), 1);
        const std::string& none = errors[0];
        RFDETR_ASSERT(none.find("5 head block") != std::string::npos);
        RFDETR_ASSERT(none.find("segmentation_head.blocks.* tensors") != std::string::npos);
        RFDETR_ASSERT(none.find("converted before") == std::string::npos);

        // Restore the default (no callback); nothing else in this file sets one.
        rfdetr_set_log_callback(nullptr, nullptr);

        // A correctly-converted 5-block model gets past the block-count guard.
        // (It still fails on the other missing seg tensors, which is fine —
        // we only assert the guard itself counts correctly.)
        fake.tensors["segmentation_head.blocks.4.dwconv.weight"] = nullptr;
        RFDETR_ASSERT_EQ_INT((int)rfdetr::count_segmentation_blocks(fake), 5);

        // Detection models have no seg head and must count zero.
        rfdetr::Model det;
        det.config.has_segmentation_head = false;
        det.config.decoder.layers = 3;
        RFDETR_ASSERT_EQ_INT((int)rfdetr::count_segmentation_blocks(det), 0);
    }

    return 0;
}

#include "test_assert.hpp"
#include "rfdetr.h"
#include <cstdio>
#include <string>

static void log_cb(rfdetr_log_level lvl, const char* msg, void*) {
    std::fprintf(stderr, "[%d] %s\n", (int)lvl, msg);
}

int main() {
    rfdetr_set_log_callback(log_cb, nullptr);
    const std::string fixtures = RFDETR_TEST_FIXTURES;
    const std::string model_path = fixtures + "/model_base.gguf";

    // Successful init
    rfdetr_params p{};
    p.model_path = model_path.c_str();
    p.n_threads  = 1;

    rfdetr_status st;
    rfdetr_context* ctx = rfdetr_init(&p, &st);
    RFDETR_ASSERT(ctx != nullptr);
    RFDETR_ASSERT_EQ_INT(st, RFDETR_OK);

    rfdetr_free(ctx);

    // Bad path -> nullptr, status set
    rfdetr_params p2{};
    p2.model_path = "/no/such/model.gguf";
    p2.n_threads  = 1;
    rfdetr_status st2;
    rfdetr_context* ctx2 = rfdetr_init(&p2, &st2);
    RFDETR_ASSERT(ctx2 == nullptr);
    RFDETR_ASSERT(st2 != RFDETR_OK);

    // Null params -> nullptr, RFDETR_ERR_INVALID_ARG
    rfdetr_status st3;
    rfdetr_context* ctx3 = rfdetr_init(nullptr, &st3);
    RFDETR_ASSERT(ctx3 == nullptr);
    RFDETR_ASSERT_EQ_INT(st3, RFDETR_ERR_INVALID_ARG);

    // rfdetr_free(nullptr) must not crash
    rfdetr_free(nullptr);

    // rfdetr_detect runs the full forward + postprocess pipeline (Plan 6c)
    rfdetr_context* ctx4 = rfdetr_init(&p, &st);
    rfdetr_image*   img  = rfdetr_image_load_file((fixtures + "/cats.png").c_str(), nullptr);
    RFDETR_ASSERT(ctx4 && img);
    rfdetr_detect_params dp{};
    dp.threshold = 0.5f; dp.top_k = 300;
    rfdetr_detection* dets = nullptr;
    size_t n = 0;
    rfdetr_status det_st = rfdetr_detect(ctx4, img, &dp, &dets, &n);
    /* The synthesized fixture uses a tiny 56×56 image (4×4=16 patches) but
     * sets num_queries=300 to match the real config — so top-K can't pick
     * 300 distinct tokens and rfdetr_model_forward bails with INFERENCE.
     * Either outcome is fine; the test verifies the path doesn't crash. */
    RFDETR_ASSERT(det_st == RFDETR_OK || det_st == RFDETR_ERR_INFERENCE);
    /* Random-weight fixture produces nonsense scores; threshold filtering means
     * typically zero detections. The CALL must succeed regardless. */
    /* If n > 0, the array must be valid and freeable. */
    if (det_st == RFDETR_OK && n > 0) {
        RFDETR_ASSERT(dets != nullptr);
        rfdetr_detections_free(dets, n);
    }

    rfdetr_image_free(img);
    rfdetr_free(ctx4);
    return 0;
}

#include "test_assert.hpp"
#include "rfdetr_capi.h"
#include <cstdlib>
#include <cstring>
#include <string>

int main() {
    const std::string fixtures = RFDETR_TEST_FIXTURES;
    const std::string model_path = fixtures + "/model_base.gguf";

    // Load
    rfdetr_handle_t h = 0;
    int rc = rfdetr_capi_load(model_path.c_str(), 1, &h);
    RFDETR_ASSERT_EQ_INT(rc, 0);
    RFDETR_ASSERT(h != 0);

    // Detect — returns JSON envelope. With the synthesized random-weight fixture,
    // scores rarely exceed the 0.5 threshold so detections is typically empty,
    // but the flat ABI's response shape (status + image + detections) is the
    // same either way.
    char* json = nullptr;
    int dr = rfdetr_capi_detect_path(h, (fixtures + "/cats.png").c_str(),
                                     0.5f, 300, &json);
    RFDETR_ASSERT_EQ_INT(dr, 0);   /* 0 = handled */
    RFDETR_ASSERT(json != nullptr);
    std::string body(json);
    rfdetr_capi_free_string(json);

    RFDETR_ASSERT(body.find("\"status\"")     != std::string::npos);
    RFDETR_ASSERT(body.find("\"detections\"") != std::string::npos);
    RFDETR_ASSERT(body.find("\"width\"")      != std::string::npos);
    RFDETR_ASSERT(body.find("\"height\"")     != std::string::npos);

    // Bad image path -> non-zero rc
    char* json2 = nullptr;
    int dr2 = rfdetr_capi_detect_path(h, "/no/such/image.png", 0.5f, 300, &json2);
    RFDETR_ASSERT(dr2 != 0);
    if (json2) rfdetr_capi_free_string(json2);

    // Unload
    int ur = rfdetr_capi_unload(h);
    RFDETR_ASSERT_EQ_INT(ur, 0);

    // Re-unload zero handle is a no-op (0)
    int ur2 = rfdetr_capi_unload(0);
    RFDETR_ASSERT_EQ_INT(ur2, 0);

    // Bad path on load
    rfdetr_handle_t h2 = 0;
    int br = rfdetr_capi_load("/no/such/file.gguf", 1, &h2);
    RFDETR_ASSERT(br != 0);
    RFDETR_ASSERT(h2 == 0);

    return 0;
}

/* tests/test_f16_model.cpp - F16 model sanity check.
 *
 * Regression test for a read-overrun bug where the loader assumed
 * backbone.pos_embed was F32 and read dim*n_train_tokens*sizeof(float)
 * bytes from the tensor — which overran the buffer for F16 tensors and
 * tripped ggml's "tensor read out of bounds" assert. See
 * src/model_loader.cpp's pos_embed handling for the fix.
 *
 * Loads models/rfdetr-base-f16.gguf (if present) and verifies:
 *   - Format version + metadata round-trip
 *   - At least some tensors are F16 (matmul-eligible weights), and lookup
 *     tensors (cls_token, pos_embed, biases, norms) stayed F32 so mixed-
 *     dtype ops like ggml_concat(cls, activation) don't error at graph build
 *   - The model loads + realizes weights without aborting (this is the
 *     actual regression — pre-fix it crashed inside model_realize_weights)
 *
 * Skips gracefully if the model isn't present so a fresh clone passes ctest.
 * Generate with:
 *   .venv/bin/python scripts/convert_rfdetr_to_gguf.py --variant base \
 *       --dtype f16 --output models/rfdetr-base-f16.gguf
 */
#include "test_assert.hpp"
#include "rfdetr.h"
#include "ggml.h"
#include "gguf.h"

#include <sys/stat.h>
#include <cstdio>
#include <cstring>
#include <string>

namespace {
bool file_exists(const std::string& p) {
    struct stat st;
    return ::stat(p.c_str(), &st) == 0;
}
}  // namespace

int main() {
    const std::string path = std::string(RFDETR_SOURCE_DIR) +
                             "/models/rfdetr-base-f16.gguf";

    if (!file_exists(path)) {
        std::fprintf(stderr,
            "[test_f16_model] SKIPPED: %s not present. Generate with\n"
            "  .venv/bin/python scripts/convert_rfdetr_to_gguf.py "
            "--variant base --dtype f16 "
            "--output models/rfdetr-base-f16.gguf\n",
            path.c_str());
        return 0;
    }

    /* --- Step 1: GGUF-level structural checks. --- */
    ggml_context* ctx = nullptr;
    gguf_init_params init_p{};
    init_p.no_alloc = true;
    init_p.ctx      = &ctx;
    gguf_context* g = gguf_init_from_file(path.c_str(), init_p);
    RFDETR_ASSERT(g != nullptr);
    RFDETR_ASSERT(ctx != nullptr);

    /* Metadata. */
    {
        int64_t kid = gguf_find_key(g, "rfdetr.format.version");
        RFDETR_ASSERT(kid >= 0);
        RFDETR_ASSERT_STR_EQ(gguf_get_val_str(g, kid), "2");
    }
    {
        int64_t kid = gguf_find_key(g, "rfdetr.variant");
        RFDETR_ASSERT(kid >= 0);
        RFDETR_ASSERT_STR_EQ(gguf_get_val_str(g, kid), "base");
    }
    {
        int64_t kid = gguf_find_key(g, "rfdetr.num_classes");
        RFDETR_ASSERT(kid >= 0);
        RFDETR_ASSERT_EQ_INT((int)gguf_get_val_u32(g, kid), 91);
    }

    /* Tensor type accounting. */
    const int64_t nt = gguf_get_n_tensors(g);
    RFDETR_ASSERT(nt > 0);

    int n_f16 = 0;
    int n_f32 = 0;
    int n_other = 0;
    for (int64_t i = 0; i < nt; ++i) {
        const char* name = gguf_get_tensor_name(g, i);
        ggml_tensor* t = ggml_get_tensor(ctx, name);
        RFDETR_ASSERT(t != nullptr);
        if (t->type == GGML_TYPE_F16)       ++n_f16;
        else if (t->type == GGML_TYPE_F32)  ++n_f32;
        else                                ++n_other;
    }

    std::fprintf(stderr,
        "[test_f16_model] tensors: F16=%d  F32=%d  other=%d  total=%lld\n",
        n_f16, n_f32, n_other, (long long)nt);

    /* Same matmul-only heuristic as the quantized variants: at least 100
     * weights cast to F16, plenty staying F32 (biases, norms, cls_token,
     * pos_embed, conv kernels). */
    RFDETR_ASSERT(n_f16 > 100);
    RFDETR_ASSERT(n_f32 > 100);
    RFDETR_ASSERT_EQ_INT(n_other, 0);

    /* Spot-check a known linear weight is F16 (e.g. backbone attn.q). */
    {
        ggml_tensor* t = ggml_get_tensor(ctx, "backbone.blocks.0.attn.q.weight");
        RFDETR_ASSERT(t != nullptr);
        RFDETR_ASSERT(t->type == GGML_TYPE_F16);
    }
    /* Spot-checks: tensors used in mixed-dtype graph ops must stay F32. */
    {
        /* cls_token gets broadcast and concatted with F32 activations. */
        ggml_tensor* t = ggml_get_tensor(ctx, "backbone.cls_token");
        RFDETR_ASSERT(t != nullptr);
        RFDETR_ASSERT(t->type == GGML_TYPE_F32);
    }
    {
        /* pos_embed is read on CPU for bicubic resampling — this is the
         * actual regression site. Pre-fix the loader would crash on F16
         * even with this F32-stay invariant absent. The fix in
         * model_loader.cpp also tolerates an F16 pos_embed via
         * ggml_fp16_to_fp32_row; we additionally keep it F32 here so the
         * resample path stays on its fast (memcpy) branch. */
        ggml_tensor* t = ggml_get_tensor(ctx, "backbone.pos_embed");
        RFDETR_ASSERT(t != nullptr);
        RFDETR_ASSERT(t->type == GGML_TYPE_F32);
    }
    {
        /* Biases stay F32 (ggml_add with F32 activation needs matching type). */
        ggml_tensor* t = ggml_get_tensor(ctx, "backbone.blocks.0.attn.q.bias");
        RFDETR_ASSERT(t != nullptr);
        RFDETR_ASSERT(t->type == GGML_TYPE_F32);
    }

    gguf_free(g);
    ggml_free(ctx);

    /* --- Step 2: full C-API load. This exercises model_realize_weights —
     * the pre-fix crash site for F16 pos_embed. --- */
    rfdetr_params p{};
    p.model_path = path.c_str();
    p.n_threads  = 1;
    rfdetr_status st = RFDETR_OK;
    rfdetr_context* rc = rfdetr_init(&p, &st);
    RFDETR_ASSERT_EQ_INT((int)st, (int)RFDETR_OK);
    RFDETR_ASSERT(rc != nullptr);

    RFDETR_ASSERT_EQ_INT((int)rfdetr_context_num_classes(rc), 91);
    RFDETR_ASSERT_EQ_INT((int)rfdetr_context_num_queries(rc), 300);
    RFDETR_ASSERT_STR_EQ(rfdetr_context_variant(rc), "base");

    rfdetr_free(rc);

    std::fprintf(stderr, "[test_f16_model] PASS\n");
    return 0;
}

/* tests/test_capi_accessors.cpp — exercises every rfdetr_capi accessor on a
 * real detection model (and, if available, a seg model for mask coverage).
 *
 * Skips gracefully when no real GGUF model is present, so a fresh clone of
 * the repo (with only the synthesized fixtures) still passes ctest. */

#include "rfdetr_capi.h"
#include "test_assert.hpp"

#include <sys/stat.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

static bool file_exists(const char* p) {
    struct stat st;
    return ::stat(p, &st) == 0;
}

static void exercise(const char* model_path, const char* image_path, bool expect_masks) {
    std::fprintf(stderr, "[test_capi_accessors] model=%s image=%s expect_masks=%d\n",
                 model_path, image_path, (int)expect_masks);

    rfdetr_handle_t h = 0;
    int rc = rfdetr_capi_load(model_path, 4, &h);
    RFDETR_ASSERT_EQ_INT(rc, 0);
    RFDETR_ASSERT(h != 0);

    /* Before any detect call, n_detections should be 0 (handle valid, batch empty). */
    RFDETR_ASSERT_EQ_INT(rfdetr_capi_get_n_detections(h), 0);

    char* json = nullptr;
    rc = rfdetr_capi_detect_path(h, image_path, 0.5f, 300, &json);
    RFDETR_ASSERT_EQ_INT(rc, 0);
    RFDETR_ASSERT(json != nullptr);
    rfdetr_capi_free_string(json);

    int n = rfdetr_capi_get_n_detections(h);
    RFDETR_ASSERT(n > 0);
    std::fprintf(stderr, "[test_capi_accessors]   -> %d detections\n", n);

    int n_masks_seen = 0;
    for (int i = 0; i < n; ++i) {
        int cid = rfdetr_capi_get_detection_class_id(h, i);
        RFDETR_ASSERT(cid >= 0 && cid < 91);

        float bbox[4];
        rc = rfdetr_capi_get_detection_box(h, i, bbox);
        RFDETR_ASSERT_EQ_INT(rc, 0);
        RFDETR_ASSERT(bbox[2] > bbox[0]);   /* x2 > x1 */
        RFDETR_ASSERT(bbox[3] > bbox[1]);   /* y2 > y1 */
        RFDETR_ASSERT(bbox[0] >= 0.0f);
        RFDETR_ASSERT(bbox[1] >= 0.0f);

        float score = rfdetr_capi_get_detection_score(h, i);
        RFDETR_ASSERT(score >= 0.5f && score <= 1.0f);

        /* Two-call sizing: first NULL+0, then a sized buffer. */
        int sz = rfdetr_capi_get_detection_class_name(h, i, nullptr, 0);
        RFDETR_ASSERT(sz > 1);                       /* at least 1 char + NUL */
        std::vector<char> name(sz);
        rc = rfdetr_capi_get_detection_class_name(h, i, name.data(), sz);
        RFDETR_ASSERT_EQ_INT(rc, sz);
        RFDETR_ASSERT(name[sz - 1] == '\0');         /* NUL-terminated */
        RFDETR_ASSERT(std::strlen(name.data()) == (size_t)sz - 1);

        /* Mask: detection-only models return 0; seg models return >0. */
        int msz = rfdetr_capi_get_detection_mask_png(h, i, nullptr, 0);
        RFDETR_ASSERT(msz >= 0);
        if (msz > 0) {
            ++n_masks_seen;
            std::vector<unsigned char> mask(msz);
            int wrote = rfdetr_capi_get_detection_mask_png(h, i, mask.data(), msz);
            RFDETR_ASSERT_EQ_INT(wrote, msz);
            /* PNG magic: 0x89 'P' 'N' 'G' 0x0D 0x0A 0x1A 0x0A */
            RFDETR_ASSERT(mask[0] == 0x89);
            RFDETR_ASSERT(mask[1] == 'P');
            RFDETR_ASSERT(mask[2] == 'N');
            RFDETR_ASSERT(mask[3] == 'G');
        }
    }

    if (expect_masks) {
        RFDETR_ASSERT(n_masks_seen > 0);
        std::fprintf(stderr, "[test_capi_accessors]   -> %d masks (PNG-encoded)\n", n_masks_seen);
    } else {
        RFDETR_ASSERT_EQ_INT(n_masks_seen, 0);
    }

    /* Sentinel checks: invalid index and NULL handle. */
    RFDETR_ASSERT_EQ_INT(rfdetr_capi_get_detection_class_id(h, -1), -1);
    RFDETR_ASSERT_EQ_INT(rfdetr_capi_get_detection_class_id(h, n + 99), -1);
    RFDETR_ASSERT(rfdetr_capi_get_detection_score(h, -1) < 0.0f);
    RFDETR_ASSERT_EQ_INT(rfdetr_capi_get_detection_mask_png(h, -1, nullptr, 0), -1);
    RFDETR_ASSERT_EQ_INT(rfdetr_capi_get_n_detections(0), -1);

    /* Two-call sizing edge case: buf_size too small returns needed size, not -1. */
    int needed = rfdetr_capi_get_detection_class_name(h, 0, nullptr, 0);
    char tiny[1];
    int got = rfdetr_capi_get_detection_class_name(h, 0, tiny, 1);
    RFDETR_ASSERT_EQ_INT(got, needed);

    /* Stale-result check: a detect call with the same image still yields >0;
     * a detect call on a non-existent path yields rc != 0 and clears the batch. */
    char* json2 = nullptr;
    int dr_bad = rfdetr_capi_detect_path(h, "/no/such/image.png", 0.5f, 300, &json2);
    RFDETR_ASSERT(dr_bad != 0);
    if (json2) rfdetr_capi_free_string(json2);
    RFDETR_ASSERT_EQ_INT(rfdetr_capi_get_n_detections(h), 0);  /* batch cleared */

    rfdetr_capi_unload(h);
}

int main() {
    /* Resolve paths relative to the source tree so the test works regardless
     * of ctest's working directory. */
    const std::string root = std::string(RFDETR_SOURCE_DIR) + "/";
    const std::string det_paths[] = {
        root + "models/rfdetr-nano-f16.gguf",
        root + "models/rfdetr-base-f16.gguf",
        root + "models/rfdetr-small-f16.gguf",
    };
    const std::string seg_paths[] = {
        root + "models/rfdetr-seg-nano-f16.gguf",
        root + "models/rfdetr-seg-small-f16.gguf",
        root + "models/rfdetr-seg-medium-f16.gguf",
    };
    const std::string image_path = root + "tests/fixtures/ci/test_image.jpg";

    if (!file_exists(image_path.c_str())) {
        std::fprintf(stderr, "[test_capi_accessors] SKIP: %s not found\n",
                     image_path.c_str());
        return 0;
    }

    const char* det_model = nullptr;
    for (const auto& p : det_paths) {
        if (file_exists(p.c_str())) { det_model = p.c_str(); break; }
    }
    const char* seg_model = nullptr;
    for (const auto& p : seg_paths) {
        if (file_exists(p.c_str())) { seg_model = p.c_str(); break; }
    }

    if (!det_model && !seg_model) {
        std::fprintf(stderr,
                     "[test_capi_accessors] SKIP: no rfdetr GGUF found in %smodels/\n",
                     root.c_str());
        return 0;
    }

    if (det_model) exercise(det_model, image_path.c_str(), /*expect_masks=*/false);
    if (seg_model) exercise(seg_model, image_path.c_str(), /*expect_masks=*/true);
    return 0;
}

/* Synthesizes a minimal rfdetr-base GGUF (format v2) for unit tests. No
 * PyTorch needed. Writes all metadata keys the loader will read, plus the
 * full expected tensor set (zero-initialized tensors of the right shapes).
 *
 * Per-tensor dimensions are shrunk (image_size=56, bb_dim=64, ffn=128,
 * etc.) so the output stays small while preserving the FULL shape
 * STRUCTURE of rfdetr-base (12 backbone blocks with separate Q/K/V +
 * layer-scale gammas, C2f single-scale projector, 13 two-stage groups,
 * 3 decoder layers with deformable cross-attn, shared heads).
 *
 * 486 tensors total. See docs/conversion.md for the schema contract.
 *
 * Tensor dtype defaults to F32; pass --dtype f16 to emit F16 (used to test
 * forward-compat with quantized weights). */

#include "ggml.h"
#include "gguf.h"

#include <algorithm>
#include <cstdio>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <random>
#include <string>
#include <vector>

namespace {

struct VariantCfg {
    const char*           name                   = "base";
    uint32_t              image_size             = 56;
    uint32_t              patch_size             = 14;
    uint32_t              num_queries            = 300;
    uint32_t              group_detr             = 13;
    uint32_t              num_classes            = 91;

    /* Backbone (DINOv2-small, shrunk) */
    uint32_t              bb_dim                 = 64;
    uint32_t              bb_depth               = 12;
    uint32_t              bb_heads               = 8;     // 8 divides 64 cleanly
    uint32_t              bb_ffn                 = 128;
    uint32_t              bb_num_windows         = 4;
    std::vector<int32_t>  bb_global_attn_indices = {2, 5, 8, 11};
    std::vector<int32_t>  bb_out_feature_indices = {2, 5, 8, 11};
    uint32_t              bb_pos_embed_train_size = 4;   // 4*4 + 1 = 17 tokens

    /* Projector (single P4 C2f, shrunk) */
    uint32_t              proj_in_dim            = 256;  // 4 * bb_dim
    uint32_t              proj_out_dim           = 64;
    uint32_t              proj_bottleneck_dim    = 32;
    uint32_t              proj_n_bottlenecks     = 3;

    /* Decoder (shrunk) */
    uint32_t              dec_layers             = 3;
    uint32_t              dec_model_dim          = 64;
    uint32_t              dec_ffn_dim            = 128;
    uint32_t              dec_self_attn_heads    = 8;
    uint32_t              dec_cross_attn_heads   = 8;    // 16 in real (with d=256, head=16); fixture uses 8 → head=8
    uint32_t              dec_cross_attn_n_levels = 1;
    uint32_t              dec_cross_attn_n_points = 2;

    /* Two-stage */
    uint32_t              two_stage_n_groups     = 13;
};

/* The 80 COCO class names placed at their canonical 1-indexed logit
 * positions in a 91-slot table. Index 0 is unused (background) in
 * standard COCO, but rfdetr's class_embed outputs are 91-wide with the
 * 80 COCO names interleaved with reserved/unused IDs.
 *
 * For test simplicity our fixture places "person" at slot 0 and
 * "toothbrush" at slot 90, with the rest filled in canonical positions.
 * The exact mapping is fixture-internal — real converted weights will use
 * the upstream COCO index convention.
 *
 * The historical "thing" gaps (reserved IDs) in standard COCO are at:
 *   12, 26, 29, 30, 45, 66, 68, 69, 71, 83.
 * Those slots get the placeholder "" in our fixture. */
struct CocoEntry { uint32_t idx; const char* name; };
const CocoEntry COCO[] = {
    { 0,"person"},{ 1,"bicycle"},{ 2,"car"},{ 3,"motorcycle"},{ 4,"airplane"},
    { 5,"bus"},{ 6,"train"},{ 7,"truck"},{ 8,"boat"},{ 9,"traffic light"},
    {10,"fire hydrant"},{11,"stop sign"},{13,"parking meter"},{14,"bench"},
    {15,"bird"},{16,"cat"},{17,"dog"},{18,"horse"},{19,"sheep"},{20,"cow"},
    {21,"elephant"},{22,"bear"},{23,"zebra"},{24,"giraffe"},{25,"backpack"},
    {27,"umbrella"},{28,"handbag"},{31,"tie"},{32,"suitcase"},{33,"frisbee"},
    {34,"skis"},{35,"snowboard"},{36,"sports ball"},{37,"kite"},
    {38,"baseball bat"},{39,"baseball glove"},{40,"skateboard"},
    {41,"surfboard"},{42,"tennis racket"},{43,"bottle"},{44,"wine glass"},
    {46,"cup"},{47,"fork"},{48,"knife"},{49,"spoon"},{50,"bowl"},
    {51,"banana"},{52,"apple"},{53,"sandwich"},{54,"orange"},{55,"broccoli"},
    {56,"carrot"},{57,"hot dog"},{58,"pizza"},{59,"donut"},{60,"cake"},
    {61,"chair"},{62,"couch"},{63,"potted plant"},{64,"bed"},{65,"dining table"},
    {67,"toilet"},{70,"tv"},{72,"laptop"},{73,"mouse"},{74,"remote"},
    {75,"keyboard"},{76,"cell phone"},{77,"microwave"},{78,"oven"},
    {79,"toaster"},{80,"sink"},{81,"refrigerator"},{82,"book"},{84,"clock"},
    {85,"vase"},{86,"scissors"},{87,"teddy bear"},{88,"hair drier"},
    /* Place toothbrush at slot 90 (last) so tests can assert on tail slot. */
    {90,"toothbrush"},
};

std::vector<std::string> build_class_names(uint32_t n_classes) {
    /* gguf_set_arr_str rejects empty strings on some implementations; use
     * "" placeholder elements for reserved/unused slots. */
    std::vector<std::string> v(n_classes, "");
    for (const auto& e : COCO) {
        if (e.idx < n_classes) v[e.idx] = e.name;
    }
    return v;
}

ggml_tensor* make_tensor(ggml_context* ctx, const char* name,
                         ggml_type type, int64_t d0, int64_t d1 = 1,
                         int64_t d2 = 1, int64_t d3 = 1) {
    ggml_tensor* t;
    if (d3 > 1)      t = ggml_new_tensor_4d(ctx, type, d0, d1, d2, d3);
    else if (d2 > 1) t = ggml_new_tensor_3d(ctx, type, d0, d1, d2);
    else if (d1 > 1) t = ggml_new_tensor_2d(ctx, type, d0, d1);
    else             t = ggml_new_tensor_1d(ctx, type, d0);
    ggml_set_name(t, name);
    return t;
}

void add_all_tensors(ggml_context* ctx, std::vector<ggml_tensor*>& out,
                     const VariantCfg& v, ggml_type tensor_dtype) {
    const ggml_type F = tensor_dtype;

    /* Convenient shorthands */
    const int64_t  bb_dim   = v.bb_dim;
    const int64_t  bb_ffn   = v.bb_ffn;
    const int64_t  ps       = v.patch_size;
    const int64_t  pos_grid = v.bb_pos_embed_train_size;
    const int64_t  n_tokens_train = pos_grid * pos_grid + 1; /* +1 for CLS */

    const int64_t  proj_in   = v.proj_in_dim;
    const int64_t  proj_out  = v.proj_out_dim;
    const int64_t  proj_bnk  = v.proj_bottleneck_dim;
    const int64_t  proj_cv2_in = proj_out + (int64_t)v.proj_n_bottlenecks * proj_bnk; // C2f cv2 input

    const int64_t  dm       = v.dec_model_dim;
    const int64_t  dffn     = v.dec_ffn_dim;
    const int64_t  n_offset = 2 * (int64_t)v.dec_cross_attn_heads
                              * v.dec_cross_attn_n_levels
                              * v.dec_cross_attn_n_points;        // sampling_offsets out
    const int64_t  n_wt     = (int64_t)v.dec_cross_attn_heads
                              * v.dec_cross_attn_n_levels
                              * v.dec_cross_attn_n_points;        // attention_weights out
    const int64_t  nq       = v.num_queries;
    const int64_t  nc       = v.num_classes;

    /* ---- Backbone embeddings (4) ---- */
    /* Conv2d weight: PyTorch (out, in, kh, kw) → ggml ne (kw, kh, in, out) */
    out.push_back(make_tensor(ctx, "backbone.patch_embed.weight", F, ps, ps, 3, bb_dim));
    out.push_back(make_tensor(ctx, "backbone.patch_embed.bias",   F, bb_dim));
    out.push_back(make_tensor(ctx, "backbone.cls_token",          F, bb_dim));
    out.push_back(make_tensor(ctx, "backbone.pos_embed",          F, bb_dim, n_tokens_train));

    /* ---- Backbone blocks (18 per block) ---- */
    for (uint32_t i = 0; i < v.bb_depth; ++i) {
        std::string p = "backbone.blocks." + std::to_string(i) + ".";
        out.push_back(make_tensor(ctx, (p + "norm1.weight").c_str(), F, bb_dim));
        out.push_back(make_tensor(ctx, (p + "norm1.bias").c_str(),   F, bb_dim));
        /* Linear weights: PyTorch (out, in) → ggml ne (in, out) */
        out.push_back(make_tensor(ctx, (p + "attn.q.weight").c_str(),    F, bb_dim, bb_dim));
        out.push_back(make_tensor(ctx, (p + "attn.q.bias").c_str(),      F, bb_dim));
        out.push_back(make_tensor(ctx, (p + "attn.k.weight").c_str(),    F, bb_dim, bb_dim));
        out.push_back(make_tensor(ctx, (p + "attn.k.bias").c_str(),      F, bb_dim));
        out.push_back(make_tensor(ctx, (p + "attn.v.weight").c_str(),    F, bb_dim, bb_dim));
        out.push_back(make_tensor(ctx, (p + "attn.v.bias").c_str(),      F, bb_dim));
        out.push_back(make_tensor(ctx, (p + "attn.proj.weight").c_str(), F, bb_dim, bb_dim));
        out.push_back(make_tensor(ctx, (p + "attn.proj.bias").c_str(),   F, bb_dim));
        out.push_back(make_tensor(ctx, (p + "layer_scale1").c_str(),     F, bb_dim));
        out.push_back(make_tensor(ctx, (p + "norm2.weight").c_str(),     F, bb_dim));
        out.push_back(make_tensor(ctx, (p + "norm2.bias").c_str(),       F, bb_dim));
        out.push_back(make_tensor(ctx, (p + "mlp.fc1.weight").c_str(),   F, bb_dim, bb_ffn));
        out.push_back(make_tensor(ctx, (p + "mlp.fc1.bias").c_str(),     F, bb_ffn));
        out.push_back(make_tensor(ctx, (p + "mlp.fc2.weight").c_str(),   F, bb_ffn, bb_dim));
        out.push_back(make_tensor(ctx, (p + "mlp.fc2.bias").c_str(),     F, bb_dim));
        out.push_back(make_tensor(ctx, (p + "layer_scale2").c_str(),     F, bb_dim));
    }
    /* ---- Backbone final norm (2) ---- */
    out.push_back(make_tensor(ctx, "backbone.norm.weight", F, bb_dim));
    out.push_back(make_tensor(ctx, "backbone.norm.bias",   F, bb_dim));

    /* ---- Projector (single P4 C2f, 26 tensors) ----
     * Conv2d weight ne: (kw, kh, in, out). cv1/cv2 are 1×1; bottlenecks 3×3. */
    out.push_back(make_tensor(ctx, "projector.cv1.conv.weight", F, 1, 1, proj_in,  proj_out));
    out.push_back(make_tensor(ctx, "projector.cv1.norm.weight", F, proj_out));
    out.push_back(make_tensor(ctx, "projector.cv1.norm.bias",   F, proj_out));
    out.push_back(make_tensor(ctx, "projector.cv2.conv.weight", F, 1, 1, proj_cv2_in, proj_out));
    out.push_back(make_tensor(ctx, "projector.cv2.norm.weight", F, proj_out));
    out.push_back(make_tensor(ctx, "projector.cv2.norm.bias",   F, proj_out));
    for (uint32_t j = 0; j < v.proj_n_bottlenecks; ++j) {
        std::string p = "projector.bottleneck." + std::to_string(j) + ".";
        out.push_back(make_tensor(ctx, (p + "cv1.conv.weight").c_str(), F, 3, 3, proj_bnk, proj_bnk));
        out.push_back(make_tensor(ctx, (p + "cv1.norm.weight").c_str(), F, proj_bnk));
        out.push_back(make_tensor(ctx, (p + "cv1.norm.bias").c_str(),   F, proj_bnk));
        out.push_back(make_tensor(ctx, (p + "cv2.conv.weight").c_str(), F, 3, 3, proj_bnk, proj_bnk));
        out.push_back(make_tensor(ctx, (p + "cv2.norm.weight").c_str(), F, proj_bnk));
        out.push_back(make_tensor(ctx, (p + "cv2.norm.bias").c_str(),   F, proj_bnk));
    }
    out.push_back(make_tensor(ctx, "projector.final_norm.weight", F, proj_out));
    out.push_back(make_tensor(ctx, "projector.final_norm.bias",   F, proj_out));

    /* ---- Two-stage groups (12 per group × 13 = 156) ---- */
    for (uint32_t g = 0; g < v.two_stage_n_groups; ++g) {
        const std::string gi = std::to_string(g);
        out.push_back(make_tensor(ctx, ("two_stage.enc_output." + gi + ".weight").c_str(), F, dm, dm));
        out.push_back(make_tensor(ctx, ("two_stage.enc_output." + gi + ".bias").c_str(),   F, dm));
        out.push_back(make_tensor(ctx, ("two_stage.enc_output_norm." + gi + ".weight").c_str(), F, dm));
        out.push_back(make_tensor(ctx, ("two_stage.enc_output_norm." + gi + ".bias").c_str(),   F, dm));
        out.push_back(make_tensor(ctx, ("two_stage.enc_out_class_embed." + gi + ".weight").c_str(), F, dm, nc));
        out.push_back(make_tensor(ctx, ("two_stage.enc_out_class_embed." + gi + ".bias").c_str(),   F, nc));
        /* MLP: dm → dm → dm → 4 */
        out.push_back(make_tensor(ctx, ("two_stage.enc_out_bbox_embed." + gi + ".layers.0.weight").c_str(), F, dm, dm));
        out.push_back(make_tensor(ctx, ("two_stage.enc_out_bbox_embed." + gi + ".layers.0.bias").c_str(),   F, dm));
        out.push_back(make_tensor(ctx, ("two_stage.enc_out_bbox_embed." + gi + ".layers.1.weight").c_str(), F, dm, dm));
        out.push_back(make_tensor(ctx, ("two_stage.enc_out_bbox_embed." + gi + ".layers.1.bias").c_str(),   F, dm));
        out.push_back(make_tensor(ctx, ("two_stage.enc_out_bbox_embed." + gi + ".layers.2.weight").c_str(), F, dm, 4));
        out.push_back(make_tensor(ctx, ("two_stage.enc_out_bbox_embed." + gi + ".layers.2.bias").c_str(),   F, 4));
    }

    /* ---- Decoder queries (group-0 slice, 2 tensors) ---- */
    out.push_back(make_tensor(ctx, "decoder.queries.feat",      F, dm, nq));
    out.push_back(make_tensor(ctx, "decoder.queries.refpoints", F, 4,  nq));

    /* ---- Decoder ref_point_head (4 tensors): MLP (2*dm) → dm → dm ----
     * Layer 0: PyTorch shape (dm, 2*dm) — refpoints sinusoidally embedded
     *   with num_pos_feats = dm/2 per axis × 4 axes (cx,cy,w,h) = 2*dm
     *   features, projected down to dm.
     *   ggml ne (in, out) = (2*dm, dm)
     * Layer 1: (dm, dm) */
    out.push_back(make_tensor(ctx, "decoder.ref_point_head.layers.0.weight", F, 2 * dm, dm));
    out.push_back(make_tensor(ctx, "decoder.ref_point_head.layers.0.bias",   F, dm));
    out.push_back(make_tensor(ctx, "decoder.ref_point_head.layers.1.weight", F, dm, dm));
    out.push_back(make_tensor(ctx, "decoder.ref_point_head.layers.1.bias",   F, dm));

    /* ---- Decoder layers (22 per layer) ---- */
    for (uint32_t i = 0; i < v.dec_layers; ++i) {
        std::string p = "decoder.layers." + std::to_string(i) + ".";
        /* Self-attention (packed QKV à la nn.MultiheadAttention) */
        out.push_back(make_tensor(ctx, (p + "self_attn.in_proj.weight").c_str(),  F, dm, 3 * dm));
        out.push_back(make_tensor(ctx, (p + "self_attn.in_proj.bias").c_str(),    F, 3 * dm));
        out.push_back(make_tensor(ctx, (p + "self_attn.out_proj.weight").c_str(), F, dm, dm));
        out.push_back(make_tensor(ctx, (p + "self_attn.out_proj.bias").c_str(),   F, dm));
        out.push_back(make_tensor(ctx, (p + "norm1.weight").c_str(),              F, dm));
        out.push_back(make_tensor(ctx, (p + "norm1.bias").c_str(),                F, dm));

        /* Deformable cross-attention */
        out.push_back(make_tensor(ctx, (p + "cross_attn.sampling_offsets.weight").c_str(),  F, dm, n_offset));
        out.push_back(make_tensor(ctx, (p + "cross_attn.sampling_offsets.bias").c_str(),    F, n_offset));
        out.push_back(make_tensor(ctx, (p + "cross_attn.attention_weights.weight").c_str(), F, dm, n_wt));
        out.push_back(make_tensor(ctx, (p + "cross_attn.attention_weights.bias").c_str(),   F, n_wt));
        out.push_back(make_tensor(ctx, (p + "cross_attn.value_proj.weight").c_str(),        F, dm, dm));
        out.push_back(make_tensor(ctx, (p + "cross_attn.value_proj.bias").c_str(),          F, dm));
        out.push_back(make_tensor(ctx, (p + "cross_attn.output_proj.weight").c_str(),       F, dm, dm));
        out.push_back(make_tensor(ctx, (p + "cross_attn.output_proj.bias").c_str(),         F, dm));
        out.push_back(make_tensor(ctx, (p + "norm2.weight").c_str(),                        F, dm));
        out.push_back(make_tensor(ctx, (p + "norm2.bias").c_str(),                          F, dm));

        /* FFN */
        out.push_back(make_tensor(ctx, (p + "linear1.weight").c_str(), F, dm, dffn));
        out.push_back(make_tensor(ctx, (p + "linear1.bias").c_str(),   F, dffn));
        out.push_back(make_tensor(ctx, (p + "linear2.weight").c_str(), F, dffn, dm));
        out.push_back(make_tensor(ctx, (p + "linear2.bias").c_str(),   F, dm));

        out.push_back(make_tensor(ctx, (p + "norm3.weight").c_str(), F, dm));
        out.push_back(make_tensor(ctx, (p + "norm3.bias").c_str(),   F, dm));
    }

    /* ---- Decoder final norm (2) ---- */
    out.push_back(make_tensor(ctx, "decoder.norm.weight", F, dm));
    out.push_back(make_tensor(ctx, "decoder.norm.bias",   F, dm));

    /* ---- Heads (shared single instances, 8 tensors) ---- */
    out.push_back(make_tensor(ctx, "heads.class_embed.weight", F, dm, nc));
    out.push_back(make_tensor(ctx, "heads.class_embed.bias",   F, nc));
    /* bbox MLP: dm → dm → dm → 4 */
    out.push_back(make_tensor(ctx, "heads.bbox_embed.layers.0.weight", F, dm, dm));
    out.push_back(make_tensor(ctx, "heads.bbox_embed.layers.0.bias",   F, dm));
    out.push_back(make_tensor(ctx, "heads.bbox_embed.layers.1.weight", F, dm, dm));
    out.push_back(make_tensor(ctx, "heads.bbox_embed.layers.1.bias",   F, dm));
    out.push_back(make_tensor(ctx, "heads.bbox_embed.layers.2.weight", F, dm, 4));
    out.push_back(make_tensor(ctx, "heads.bbox_embed.layers.2.bias",   F, 4));
}

}  // namespace

int main(int argc, char** argv) {
    if (argc < 2) {
        std::fprintf(stderr, "usage: gen_model_gguf <out_path>\n");
        return 1;
    }
    const char* out_path = argv[1];
    const char* skip_name = nullptr;
    /* Left null by default so the fixture carries no
     * rfdetr.preprocess.resize_mode key at all, which is what a GGUF converted
     * before that key existed looks like. */
    const char* resize_mode = nullptr;
    unsigned seed = 0;
    bool seeded = false;
    ggml_type tensor_dtype = GGML_TYPE_F32;
    for (int i = 2; i + 1 < argc; ++i) {
        if (std::strcmp(argv[i], "--missing") == 0) {
            skip_name = argv[i + 1];
        } else if (std::strcmp(argv[i], "--resize-mode") == 0) {
            resize_mode = argv[i + 1];
        } else if (std::strcmp(argv[i], "--seed") == 0) {
            seed = (unsigned)std::strtoul(argv[i + 1], nullptr, 10);
            seeded = true;
        } else if (std::strcmp(argv[i], "--dtype") == 0) {
            std::string val = argv[i + 1];
            if      (val == "f16") tensor_dtype = GGML_TYPE_F16;
            else if (val == "f32") tensor_dtype = GGML_TYPE_F32;
            else {
                std::fprintf(stderr, "unknown --dtype: %s\n", val.c_str());
                return 5;
            }
        }
    }
    VariantCfg v;

    ggml_init_params iparams{};
    iparams.mem_size   = 512 * 1024 * 1024;
    iparams.mem_buffer = nullptr;
    iparams.no_alloc   = false;
    ggml_context* ctx = ggml_init(iparams);
    if (!ctx) { std::fprintf(stderr, "ggml_init failed\n"); return 2; }

    std::vector<ggml_tensor*> tensors;
    tensors.reserve(600);
    add_all_tensors(ctx, tensors, v, tensor_dtype);

    if (skip_name) {
        auto it = std::remove_if(tensors.begin(), tensors.end(),
            [&](ggml_tensor* t) { return std::string(ggml_get_name(t)) == skip_name; });
        tensors.erase(it, tensors.end());
    }

    /* Initialize tensor data. With --seed N, fill with N(0, 0.02) (PyTorch
     * default init scale); otherwise zero-fill so the GGUF writer reads
     * valid bytes. */
    if (seeded) {
        std::mt19937 rng(seed);
        std::normal_distribution<float> dist(0.0f, 0.02f);
        for (auto* t : tensors) {
            size_t nelem = ggml_nelements(t);
            if (t->type == GGML_TYPE_F32) {
                float* p = (float*)t->data;
                for (size_t i = 0; i < nelem; ++i) p[i] = dist(rng);
            } else if (t->type == GGML_TYPE_F16) {
                ggml_fp16_t* p = (ggml_fp16_t*)t->data;
                for (size_t i = 0; i < nelem; ++i) {
                    p[i] = ggml_fp32_to_fp16(dist(rng));
                }
            } else {
                std::fprintf(stderr, "gen_model_gguf: unsupported type for tensor %s\n",
                             ggml_get_name(t));
                return 4;
            }
        }
    } else {
        for (auto* t : tensors) {
            std::memset(t->data, 0, ggml_nbytes(t));
        }
    }

    gguf_context* gguf = gguf_init_empty();

    /* --- Top-level / format --- */
    gguf_set_val_str(gguf, "general.architecture",    "rfdetr");
    gguf_set_val_str(gguf, "rfdetr.format.version",   "2");
    gguf_set_val_str(gguf, "rfdetr.variant",          v.name);
    gguf_set_val_u32(gguf, "rfdetr.image_size",       v.image_size);
    gguf_set_val_u32(gguf, "rfdetr.patch_size",       v.patch_size);
    gguf_set_val_u32(gguf, "rfdetr.num_queries",      v.num_queries);
    gguf_set_val_u32(gguf, "rfdetr.group_detr",       v.group_detr);
    gguf_set_val_u32(gguf, "rfdetr.num_classes",      v.num_classes);

    /* class_names: 91-slot vector, COCO names at canonical positions */
    std::vector<std::string> class_names = build_class_names(v.num_classes);
    std::vector<const char*> class_names_cstr;
    class_names_cstr.reserve(class_names.size());
    for (const auto& s : class_names) class_names_cstr.push_back(s.c_str());
    gguf_set_arr_str(gguf, "rfdetr.class_names", class_names_cstr.data(),
                     class_names_cstr.size());

    /* --- Preprocess --- */
    float mean[3] = {0.485f, 0.456f, 0.406f};
    float stdv[3] = {0.229f, 0.224f, 0.225f};
    gguf_set_arr_data(gguf, "rfdetr.preprocess.mean", GGUF_TYPE_FLOAT32, mean, 3);
    gguf_set_arr_data(gguf, "rfdetr.preprocess.std",  GGUF_TYPE_FLOAT32, stdv, 3);
    /* Only written when --resize-mode is given, so the default fixture keeps
     * exercising the absent-key (legacy) path. */
    if (resize_mode) {
        gguf_set_val_str(gguf, "rfdetr.preprocess.resize_mode", resize_mode);
    }

    /* --- Backbone --- */
    gguf_set_val_u32(gguf, "rfdetr.backbone.dim",                  v.bb_dim);
    gguf_set_val_u32(gguf, "rfdetr.backbone.depth",                v.bb_depth);
    gguf_set_val_u32(gguf, "rfdetr.backbone.heads",                v.bb_heads);
    gguf_set_val_u32(gguf, "rfdetr.backbone.ffn_dim",              v.bb_ffn);
    gguf_set_val_u32(gguf, "rfdetr.backbone.num_windows",          v.bb_num_windows);
    gguf_set_val_u32(gguf, "rfdetr.backbone.pos_embed_train_size", v.bb_pos_embed_train_size);
    gguf_set_arr_data(gguf, "rfdetr.backbone.global_attn_indices",
                      GGUF_TYPE_INT32, v.bb_global_attn_indices.data(),
                      v.bb_global_attn_indices.size());
    gguf_set_arr_data(gguf, "rfdetr.backbone.out_feature_indices",
                      GGUF_TYPE_INT32, v.bb_out_feature_indices.data(),
                      v.bb_out_feature_indices.size());

    /* --- Projector --- */
    gguf_set_val_u32(gguf, "rfdetr.projector.in_dim",         v.proj_in_dim);
    gguf_set_val_u32(gguf, "rfdetr.projector.out_dim",        v.proj_out_dim);
    gguf_set_val_u32(gguf, "rfdetr.projector.bottleneck_dim", v.proj_bottleneck_dim);
    gguf_set_val_u32(gguf, "rfdetr.projector.n_bottlenecks",  v.proj_n_bottlenecks);

    /* --- Decoder --- */
    gguf_set_val_u32(gguf, "rfdetr.decoder.layers",              v.dec_layers);
    gguf_set_val_u32(gguf, "rfdetr.decoder.model_dim",           v.dec_model_dim);
    gguf_set_val_u32(gguf, "rfdetr.decoder.ffn_dim",             v.dec_ffn_dim);
    gguf_set_val_u32(gguf, "rfdetr.decoder.self_attn_heads",     v.dec_self_attn_heads);
    gguf_set_val_u32(gguf, "rfdetr.decoder.cross_attn_heads",    v.dec_cross_attn_heads);
    gguf_set_val_u32(gguf, "rfdetr.decoder.cross_attn_n_levels", v.dec_cross_attn_n_levels);
    gguf_set_val_u32(gguf, "rfdetr.decoder.cross_attn_n_points", v.dec_cross_attn_n_points);

    /* --- Two-stage --- */
    gguf_set_val_u32(gguf, "rfdetr.two_stage.n_groups", v.two_stage_n_groups);

    for (auto* t : tensors) gguf_add_tensor(gguf, t);

    if (!gguf_write_to_file(gguf, out_path, /*only_meta*/ false)) {
        std::fprintf(stderr, "gguf_write_to_file failed for %s\n", out_path);
        gguf_free(gguf);
        ggml_free(ctx);
        return 3;
    }

    gguf_free(gguf);
    ggml_free(ctx);
    std::printf("wrote %s (%zu tensors)\n", out_path, tensors.size());
    return 0;
}

#ifndef RFDETR_CAPI_H
#define RFDETR_CAPI_H

#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/* Flat handle. All functions return int status; 0 = ok, negative = error. */
typedef uintptr_t rfdetr_handle_t;

int rfdetr_capi_load(const char* model_path, int n_threads, rfdetr_handle_t* out_handle);
int rfdetr_capi_unload(rfdetr_handle_t handle);

/* Detect on an image file path. Output is a JSON string (caller frees with
 * rfdetr_capi_free_string). */
int rfdetr_capi_detect_path(rfdetr_handle_t handle,
                            const char* image_path,
                            float threshold, uint32_t top_k,
                            char** out_json);

/* Detect on an in-memory image buffer (encoded PNG/JPEG bytes). */
int rfdetr_capi_detect_buffer(rfdetr_handle_t handle,
                              const uint8_t* bytes, size_t len,
                              float threshold, uint32_t top_k,
                              char** out_json);

void rfdetr_capi_free_string(char* s);

/* --------------------------------------------------------------------------
 * Per-detection accessors (LocalAI / purego pattern, mirrors sam3.cpp).
 *
 * `rfdetr_capi_detect_path` / `_detect_buffer` persist the detection batch on
 * the handle. The following accessors read from that batch without
 * re-parsing the JSON envelope. Every detect call clears the previous batch.
 * -------------------------------------------------------------------------- */

/* Number of detections from the most recent detect call on `handle`.
 * Returns 0 if no detect call has been made or it returned no detections.
 * Returns -1 if `handle` is invalid (0/NULL). */
int rfdetr_capi_get_n_detections(rfdetr_handle_t handle);

/* Class id of detection `i` (0-indexed). Returns -1 if `i` is out of range
 * or `handle` is invalid. */
int rfdetr_capi_get_detection_class_id(rfdetr_handle_t handle, int i);

/* Bounding box of detection `i` in original-image pixel coordinates.
 * Writes 4 floats to `out_xyxy` (x1, y1, x2, y2). Returns 0 on success,
 * -1 on invalid handle/index/NULL out pointer. */
int rfdetr_capi_get_detection_box(rfdetr_handle_t handle, int i, float out_xyxy[4]);

/* Confidence score of detection `i`. Returns -1.0 on invalid handle/index. */
float rfdetr_capi_get_detection_score(rfdetr_handle_t handle, int i);

/* Class name of detection `i` (NUL-terminated UTF-8). Two-call sizing:
 *   - pass NULL / 0 to get the required buffer size (including NUL byte);
 *   - pass a buffer >= required size to write the string.
 * Returns the required size (>= 1) on success, -1 on invalid handle/index.
 */
int rfdetr_capi_get_detection_class_name(rfdetr_handle_t handle, int i,
                                         char* buf, int buf_size);

/* PNG-encoded binary segmentation mask of detection `i` (1 byte per pixel,
 * 0 = background, 255 = foreground, same dimensions as the source image).
 *
 * Two-call sizing:
 *   - pass NULL / 0 to get the required buffer size (encoded PNG byte length);
 *   - pass a buffer >= required size to write the encoded bytes.
 *
 * Returns the required size on success, 0 if this detection has no mask
 * (i.e., the model is a detection-only variant), or -1 on invalid
 * handle/index. */
int rfdetr_capi_get_detection_mask_png(rfdetr_handle_t handle, int i,
                                       unsigned char* buf, int buf_size);

#ifdef __cplusplus
} /* extern "C" */
#endif

