#include "rfdetr_capi.h"
#include "rfdetr.h"
#include "image_io.hpp"
#include "common.hpp"

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <new>
#include <sstream>
#include <string>
#include <vector>

namespace {

/* Per-handle storage. The flat C-API previously stored only the
 * `rfdetr_context*` cast to `uintptr_t`. To support the accessor pattern used
 * by LocalAI's purego layer (number of detections + per-detection field
 * lookups + PNG-encoded masks), each `rfdetr_capi_load` now allocates this
 * wrapper. `rfdetr_capi_detect_path` / `_detect_buffer` populate
 * `last_detections` (and `last_json`) on every call; accessors read from
 * `last_detections`.
 *
 * Stale results from a prior detect call are cleared at the start of every
 * new detect call, so an accessor following a failed detect returns "no
 * detections" rather than leaking the previous batch. */
struct CapiHandle {
    rfdetr_context* ctx = nullptr;

    struct DetectionStore {
        int class_id = 0;
        std::string class_name;  // owned copy (rfdetr_detection.class_name is borrowed)
        float score = 0.0f;
        float x1 = 0, y1 = 0, x2 = 0, y2 = 0;
        std::vector<uint8_t> mask_png;  // empty for non-seg models / no mask
        int mask_w = 0;
        int mask_h = 0;
    };
    std::vector<DetectionStore> last_detections;
    std::string last_json;
};

/* Serialize an rfdetr_context plus the result of a detect attempt into a
 * JSON envelope. The envelope always includes a `status` field so callers
 * can distinguish "model loaded but inference NYI" from "decode failure". */
std::string make_json(int img_w, int img_h, const char* status,
                      const rfdetr_detection* dets, size_t n) {
    std::ostringstream o;
    o << "{\"status\":\"" << status << "\","
      << "\"image\":{\"width\":" << img_w << ",\"height\":" << img_h << "},"
      << "\"detections\":[";
    for (size_t i = 0; i < n; ++i) {
        if (i) o << ",";
        o << "{\"class_id\":" << dets[i].class_id
          << ",\"score\":" << dets[i].score
          << ",\"x1\":" << dets[i].x1
          << ",\"y1\":" << dets[i].y1
          << ",\"x2\":" << dets[i].x2
          << ",\"y2\":" << dets[i].y2
          << "}";
    }
    o << "]}";
    return o.str();
}

char* dup_to_c(const std::string& s) {
    char* buf = (char*)std::malloc(s.size() + 1);
    if (!buf) return nullptr;
    std::memcpy(buf, s.data(), s.size());
    buf[s.size()] = '\0';
    return buf;
}

}  // namespace

extern "C" int rfdetr_capi_load(const char* model_path, int n_threads, rfdetr_handle_t* out_handle) {
    if (!model_path || !out_handle) return -1;
    *out_handle = 0;

    rfdetr_params p{};
    p.model_path = model_path;
    p.n_threads  = n_threads > 0 ? n_threads : 1;

    rfdetr_status st;
    rfdetr_context* ctx = rfdetr_init(&p, &st);
    if (!ctx) return (int)st;

    auto* h = new (std::nothrow) CapiHandle();
    if (!h) {
        rfdetr_free(ctx);
        return (int)RFDETR_ERR_OUT_OF_MEMORY;
    }
    h->ctx = ctx;

    *out_handle = (rfdetr_handle_t)h;
    return 0;
}

extern "C" int rfdetr_capi_unload(rfdetr_handle_t handle) {
    if (handle == 0) return 0;
    auto* h = (CapiHandle*)handle;
    if (h->ctx) rfdetr_free(h->ctx);
    delete h;
    return 0;
}

static int capi_detect_common(rfdetr_handle_t handle, rfdetr_image* img,
                              float threshold, uint32_t top_k, char** out_json) {
    auto* h = (CapiHandle*)handle;
    if (!h || !h->ctx || !img || !out_json) return -1;
    *out_json = nullptr;

    /* Clear any prior batch so accessors can never read stale results. */
    h->last_detections.clear();
    h->last_json.clear();

    rfdetr_detect_params dp{};
    dp.threshold = threshold;
    dp.top_k     = top_k;

    rfdetr_detection* dets = nullptr;
    size_t n = 0;
    rfdetr_status st = rfdetr_detect(h->ctx, img, &dp, &dets, &n);

    const char* status = (st == RFDETR_OK)                  ? "ok"
                       : (st == RFDETR_ERR_NOT_IMPLEMENTED) ? "not_implemented"
                       :                                       rfdetr_status_str(st);

    /* Persist the batch into the handle storage so accessors can read it.
     * Done before json serialization and dets-free so we can copy fields. */
    if (st == RFDETR_OK && dets && n > 0) {
        h->last_detections.reserve(n);
        for (size_t i = 0; i < n; ++i) {
            const rfdetr_detection& d = dets[i];
            CapiHandle::DetectionStore s;
            s.class_id   = (int)d.class_id;
            s.class_name = d.class_name ? d.class_name : "";
            s.score      = d.score;
            s.x1 = d.x1; s.y1 = d.y1; s.x2 = d.x2; s.y2 = d.y2;
            s.mask_w = d.mask_width;
            s.mask_h = d.mask_height;
            if (d.mask && d.mask_width > 0 && d.mask_height > 0) {
                rfdetr_encode_gray_png(d.mask, d.mask_width, d.mask_height, s.mask_png);
            }
            h->last_detections.push_back(std::move(s));
        }
    }

    std::string json = make_json(rfdetr_image_width(img), rfdetr_image_height(img),
                                 status, dets, n);
    rfdetr_detections_free(dets, n);

    h->last_json = json;
    *out_json = dup_to_c(json);
    if (!*out_json) return RFDETR_ERR_OUT_OF_MEMORY;
    return 0;
}

extern "C" int rfdetr_capi_detect_path(rfdetr_handle_t handle, const char* image_path,
                                       float threshold, uint32_t top_k, char** out_json) {
    if (!handle || !image_path || !out_json) return -1;
    *out_json = nullptr;

    /* Clear stale results before image load so an early-failure detect call
     * cannot leave the previous batch readable via the accessors. */
    if (auto* h = (CapiHandle*)handle) {
        h->last_detections.clear();
        h->last_json.clear();
    }

    rfdetr_status load_st;
    rfdetr_image* img = rfdetr_image_load_file(image_path, &load_st);
    if (!img) return (int)load_st;

    int rc = capi_detect_common(handle, img, threshold, top_k, out_json);
    rfdetr_image_free(img);
    return rc;
}

extern "C" int rfdetr_capi_detect_buffer(rfdetr_handle_t handle,
                                         const uint8_t* bytes, size_t len,
                                         float threshold, uint32_t top_k,
                                         char** out_json) {
    if (!handle || !bytes || len == 0 || !out_json) return -1;
    *out_json = nullptr;

    if (auto* h = (CapiHandle*)handle) {
        h->last_detections.clear();
        h->last_json.clear();
    }

    rfdetr_status load_st;
    rfdetr_image* img = rfdetr_image_load_buffer(bytes, len, &load_st);
    if (!img) return (int)load_st;

    int rc = capi_detect_common(handle, img, threshold, top_k, out_json);
    rfdetr_image_free(img);
    return rc;
}

extern "C" void rfdetr_capi_free_string(char* s) {
    std::free(s);
}

/* --------------------------------------------------------------------------
 * Accessor functions (LocalAI / purego pattern, mirrors sam3-cpp gosam3.h).
 *
 * Each call reads from the handle's `last_detections`, populated by the most
 * recent detect call. Returns sentinel values for invalid handle/index so the
 * Go side can branch on negative return codes.
 *
 * Two-call sizing pattern (class_name, mask_png): first call with NULL/0
 * returns the required buffer size; second call with a sufficient buffer
 * writes the bytes. Avoids any allocator coordination across the FFI boundary.
 * -------------------------------------------------------------------------- */

extern "C" int rfdetr_capi_get_n_detections(rfdetr_handle_t handle) {
    auto* h = (CapiHandle*)handle;
    if (!h) return -1;
    return (int)h->last_detections.size();
}

extern "C" int rfdetr_capi_get_detection_class_id(rfdetr_handle_t handle, int i) {
    auto* h = (CapiHandle*)handle;
    if (!h || i < 0 || (size_t)i >= h->last_detections.size()) return -1;
    return h->last_detections[i].class_id;
}

extern "C" int rfdetr_capi_get_detection_box(rfdetr_handle_t handle, int i, float out_xyxy[4]) {
    auto* h = (CapiHandle*)handle;
    if (!h || i < 0 || (size_t)i >= h->last_detections.size() || !out_xyxy) return -1;
    const auto& d = h->last_detections[i];
    out_xyxy[0] = d.x1;
    out_xyxy[1] = d.y1;
    out_xyxy[2] = d.x2;
    out_xyxy[3] = d.y2;
    return 0;
}

extern "C" float rfdetr_capi_get_detection_score(rfdetr_handle_t handle, int i) {
    auto* h = (CapiHandle*)handle;
    if (!h || i < 0 || (size_t)i >= h->last_detections.size()) return -1.0f;
    return h->last_detections[i].score;
}

extern "C" int rfdetr_capi_get_detection_class_name(rfdetr_handle_t handle, int i,
                                                    char* buf, int buf_size) {
    auto* h = (CapiHandle*)handle;
    if (!h || i < 0 || (size_t)i >= h->last_detections.size()) return -1;
    const std::string& s = h->last_detections[i].class_name;
    int needed = (int)s.size() + 1;  // include NUL
    if (buf == nullptr || buf_size < needed) return needed;
    std::memcpy(buf, s.data(), s.size());
    buf[s.size()] = '\0';
    return needed;
}

extern "C" int rfdetr_capi_get_detection_mask_png(rfdetr_handle_t handle, int i,
                                                  unsigned char* buf, int buf_size) {
    auto* h = (CapiHandle*)handle;
    if (!h || i < 0 || (size_t)i >= h->last_detections.size()) return -1;
    const auto& mp = h->last_detections[i].mask_png;
    if (mp.empty()) return 0;  // no mask (detection-only model)
    int needed = (int)mp.size();
    if (buf == nullptr || buf_size < needed) return needed;
    std::memcpy(buf, mp.data(), (size_t)needed);
    return needed;
}

#ifndef RFDETR_MODEL_HPP
#define RFDETR_MODEL_HPP

#include "model_loader.hpp"
#include "backend.hpp"

#include <cstdint>
#include <vector>

struct ggml_backend;
typedef struct ggml_backend* ggml_backend_t;

namespace rfdetr {

/* Host-side result of the full forward pass at inference.
 *
 *   class_logits  shape (num_classes, num_queries) row-major in this vector
 *                 (i.e. class is fastest-varying — matches ggml ne[0]=num_classes
 *                 from heads.class_logits, which is what postprocess expects).
 *                 RAW logits (apply sigmoid in postproc).
 *   bbox_cxcywh   shape (4, num_queries) row-major — (cx, cy, w, h) in [0, 1]
 *                 after bbox_reparam (delta combined with refpoints).
 *   masks         (optional, only when has_segmentation_head=true) — flat raw
 *                 mask logits in (W_mask, H_mask, num_queries) layout, with
 *                 W_mask = image_size / mask_downsample_ratio and likewise H.
 *                 Empty if the model has no seg head.
 *   mask_w, mask_h spatial extent of `masks` (0/0 if no seg head).
 *
 * On failure all vectors are empty (and status is logged via rfdetr_logf). */
struct ForwardOutput {
    std::vector<float> class_logits;   // size = num_classes * num_queries
    std::vector<float> bbox_cxcywh;    // size = 4 * num_queries
    std::vector<float> masks;          // size = mask_h * mask_w * num_queries (or 0)
    int mask_h = 0;
    int mask_w = 0;
    int num_queries = 0;
    int num_classes = 0;
};

/* Run the full forward pipeline end-to-end:
 *
 *   preprocessed input → backbone → projector → two_stage init → CPU top-K
 *   + refpoint construction → decoder → heads → bbox_reparam → output.
 *
 *   input_data: preprocessed F32 buffer, shape (image_size, image_size, 3, 1)
 *               (matches `rfdetr_preprocess` output). Already ImageNet-normalized.
 *   input_size: image_size (square, must equal model's `config.image_size`).
 *   bctx:       backend bundle (CPU + optional BLAS via sched) the model
 *               weights were realized on (weights live on bctx.cpu's buffer).
 *
 * Returns empty vectors in the ForwardOutput on failure. */
ForwardOutput rfdetr_model_forward(const Model& m,
                                   const float* input_data, int input_size,
                                   BackendCtx& bctx);

/* Single-backend overload for tests / parity harnesses that don't need BLAS
 * dispatch. Internally builds a transient BackendCtx with only `cpu` set. */
ForwardOutput rfdetr_model_forward(const Model& m,
                                   const float* input_data, int input_size,
                                   ggml_backend_t backend);

}  // namespace rfdetr

#endif

#ifndef RFDETR_MODEL_LOADER_HPP
#define RFDETR_MODEL_LOADER_HPP

#include "rfdetr.h"

#include <cstdint>
#include <string>
#include <unordered_map>
#include <vector>

struct ggml_context;
struct ggml_tensor;
struct gguf_context;
struct ggml_backend_buffer;
typedef struct ggml_backend_buffer* ggml_backend_buffer_t;
struct ggml_backend;
typedef struct ggml_backend* ggml_backend_t;

namespace rfdetr {

/* Configuration loaded from GGUF metadata. Plan 3's graph builder consumes
 * this; Plan 2's loader only populates it.
 *
 * Schema: format version "2" — see docs/conversion.md. */
struct Config {
    std::string variant;          // "base" (only supported variant for now)
    uint32_t image_size  = 0;
    uint32_t patch_size  = 0;
    uint32_t num_queries = 0;
    uint32_t group_detr  = 0;     // training-time groups; only group 0 used at inference
    uint32_t num_classes = 0;
    std::vector<std::string> class_names;
    float preprocess_mean[3] = {0, 0, 0};
    float preprocess_std[3]  = {1, 1, 1};
    /* Optional in format v2 for backward compatibility. Newly converted
     * RF-DETR >=1.9 models set this true; GGUFs without the key keep the
     * legacy stb resize so their established outputs do not change. */
    bool preprocess_bilinear_no_antialias = false;

    struct {
        uint32_t dim                  = 0;
        uint32_t depth                = 0;
        uint32_t heads                = 0;
        uint32_t ffn_dim              = 0;
        uint32_t num_windows          = 0;
        std::vector<uint32_t> global_attn_indices;
        std::vector<uint32_t> out_feature_indices;
        uint32_t pos_embed_train_size = 0;
    } backbone;

    struct {
        uint32_t in_dim         = 0;
        uint32_t out_dim        = 0;
        uint32_t bottleneck_dim = 0;
        uint32_t n_bottlenecks  = 0;
    } projector;

    struct {
        uint32_t layers              = 0;
        uint32_t model_dim           = 0;
        uint32_t ffn_dim             = 0;
        uint32_t self_attn_heads     = 0;
        uint32_t cross_attn_heads    = 0;
        uint32_t cross_attn_n_levels = 0;
        uint32_t cross_attn_n_points = 0;
    } decoder;

    struct {
        uint32_t n_groups = 0;
    } two_stage;

    /* Segmentation head: present only on RFDETRSeg* variants. When
     * `has_segmentation_head` is true, the model has additional tensors
     * (11 shared plus 6 per decoder layer) under `segmentation_head.*` and
     * the forward pass emits per-query masks at
     * (H / mask_downsample_ratio, W / mask_downsample_ratio). */
    bool has_segmentation_head    = false;
    uint32_t mask_downsample_ratio = 4;
};

/* Loaded model. Plan 2 populates `config` and `tensors` (ggml_tensor
 * descriptors from gguf_init_from_file — data is NOT loaded into a backend
 * buffer yet). Plan 3 will add a backend buffer + actual data load. */
struct Model {
    Config config;
    ::gguf_context* gguf  = nullptr;
    ::ggml_context* meta  = nullptr;  // ggml_context produced by gguf_init_from_file
    std::unordered_map<std::string, ::ggml_tensor*> tensors;

    /* Stashed during model_load so model_realize_weights can re-open the file
     * for streaming tensor data. */
    std::string path;

    /* Populated by model_realize_weights. nullptr until then. */
    ::ggml_backend_buffer_t weights = nullptr;

    /* Bicubic-interpolated backbone pos_embed for the inference resolution.
     *
     * The stored `backbone.pos_embed` tensor is the training-time embedding
     * for a 37x37 patch grid (+ CLS) → 1370 tokens. At rfdetr-base inference
     * the image is 560x560 → 40x40 = 1600 patches (+ CLS) → 1601 tokens.
     * The HF DinoV2 embedding module bicubic-interpolates the stored grid
     * at every forward call; we cache the result once at weight-realize time.
     *
     * Stored as a `(dim, N_inference_tokens)` F32 ggml tensor in `extras_ctx`
     * (allocated separately from `meta` which has a fixed-size pool). */
    ::ggml_context* extras_ctx = nullptr;
    ::ggml_backend_buffer_t extras_buf = nullptr;
    ::ggml_tensor* backbone_pos_embed_interp = nullptr;

    /* Two-stage proposal grid (4, W_inf*H_inf) F32. Constant — depends only
     * on the inference spatial extent. Populated by model_realize_weights and
     * lives in extras_ctx alongside backbone_pos_embed_interp. */
    ::ggml_tensor* proposals_grid = nullptr;
};

/* Load a model from a GGUF file at `path`. Returns nullptr on error and sets
 * `*out_status`. Caller owns the returned pointer; free with
 * `rfdetr::model_free`. */
Model* model_load(const std::string& path, rfdetr_status* out_status);

/* Free a model returned by `model_load`. Releases the gguf_context and
 * underlying ggml_context. */
void model_free(Model* m);

/* Validate that the expected tensor set for the config's variant is present
 * in `m->tensors`. Returns RFDETR_OK if all expected tensors are present,
 * RFDETR_ERR_MODEL_LOAD with a logged error otherwise. */
rfdetr_status model_validate_tensors(const Model& m);

/* Allocate a backend buffer for the model's tensors and copy data from the
 * GGUF file into it. After this call, every tensor descriptor in
 * `m.tensors` is backed by real data on the supplied backend.
 *
 * Idempotent: if `m.weights` is already non-null, returns RFDETR_OK without
 * doing anything. Returns RFDETR_ERR_MODEL_LOAD on failure (logged). */
rfdetr_status model_realize_weights(Model& m, ::ggml_backend_t backend);

/* Build the list of *expected* tensor names for a given variant config. Used
 * by both `model_validate_tensors` and the test-fixture generator. */
std::vector<std::string> expected_tensor_names(const Config& cfg);

/* Count the segmentation-head blocks actually present in `m.tensors`, by
 * probing `segmentation_head.blocks.N.dwconv.weight` for N = 0, 1, 2, ...
 * until one is missing. Returns 0 for detection models.
 *
 * A correctly converted seg model has exactly `config.decoder.layers` blocks.
 * Fewer means the file was produced before the seg-head block-count fix and
 * its masks are wrong. */
uint32_t count_segmentation_blocks(const Model& m);

}  // namespace rfdetr

#endif
